export function esc(value) {
    return value
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;');
}
export function isSafeDashboardUrl(raw) {
    try {
        const scheme = new URL(raw).protocol;
        return 'https:' === scheme || 'http:' === scheme;
    }
    catch {
        return false;
    }
}
